import { assert } from 'vitest';
import * as acorn from 'acorn';
import { tsPlugin } from '../src/index.js';

export const Parser = acorn.Parser.extend(tsPlugin() as any);

export const DtsParser = acorn.Parser.extend(
	tsPlugin({
		dts: true
	}) as any
);

export const JsxParser = acorn.Parser.extend(
	tsPlugin({
		jsx: true
	}) as any
);

export function equalNode(node, snapshot) {
	assert.deepEqual(JSON.parse(JSON.stringify(node)), snapshot, 'should be' + JSON.stringify(node));
}

export function parseDtsSource(input: string) {
	return DtsParser.parse(input, {
		sourceType: 'module',
		ecmaVersion: 'latest',
		locations: true
	});
}

export function parseJsxSource(input: string) {
	return JsxParser.parse(input, {
		sourceType: 'module',
		ecmaVersion: 'latest',
		locations: true
	});
}

export function parseSource(input: string, sourceType: 'module' | 'script' = 'module') {
	return Parser.parse(input, {
		sourceType,
		ecmaVersion: 'latest',
		locations: true
	});
}

export function parseSourceShouldThrowError(
	input: string,
	message?: string,
	sourceType: 'module' | 'script' = 'module'
) {
	try {
		Parser.parse(input, {
			sourceType,
			ecmaVersion: 'latest',
			locations: true
		});

		assert.fail('should throw an error');
	} catch (e) {
		if (message) {
			assert.equal(e.message, message);
		}
	}
}

export function generateSource(input: string[]): string {
	return input.join('\n');
}

